class Solution {public:
 int primeSubarray(vector<int>& nums,int k){
  int n=nums.size(),mx=*max_element(nums.begin(),nums.end());vector<char> prime(mx+1,true);prime[0]=false;if(mx>=1)prime[1]=false;
  for(int i=2;i*i<=mx;++i)if(prime[i])for(int j=i*i;j<=mx;j+=i)prime[j]=false;
  deque<int> mn,mxq;vector<int> pos;long long ans=0;int l=0;
  for(int r=0;r<n;++r){if(prime[nums[r]]){
   while(!mn.empty()&&nums[mn.back()]>=nums[r])mn.pop_back();mn.push_back(r);
   while(!mxq.empty()&&nums[mxq.back()]<=nums[r])mxq.pop_back();mxq.push_back(r);pos.push_back(r);
  }
   while(!mn.empty()&&!mxq.empty()&&nums[mxq.front()]-nums[mn.front()]>k){
    if(mn.front()==l)mn.pop_front();if(mxq.front()==l)mxq.pop_front();++l;
   }
   auto it=lower_bound(pos.begin(),pos.end(),l);int count=pos.end()-it;
   if(count>=2)ans+=(*(pos.end()-2)-l+1);
  }return (int)ans;
 }
};
